async function referencePlace(value,page=1){const {p,index}=referenceParts(value),place=p?.ExtRef_Children_places?.[index];if(!place)return;const stamp=referenceState.dialogStamp+1;openDialog('地名 · '+place.place_name,'<p>正在载入地名资料…</p>');try{const d=await referenceAPI('resolved_place_info',{place_tongjian_id:place.tongjian_id,page,page_size:10});if(stamp!==referenceState.dialogStamp||!$('#dialog').open)return;const profile=d.resolved_profile||{},rows=d.occurrence_page||{items:[],current_page:1,total_pages:1};$('#dialog-body').innerHTML=`<h3>${E(profile.standard_name||d.place_name||place.place_name)}</h3><p>${E(profile.intro||place.place_note||'暂无简介')}</p><p>今地：${E(profile.modern_location||'尚无明确对应')}</p>${profile.lon_min!=null?`<p class="search-status">范围：经度 ${E(profile.lon_min)}–${E(profile.lon_max)}，纬度 ${E(profile.lat_min)}–${E(profile.lat_max)}</p>`:''}${referencePaging(rows,'place',value)}${referenceOccurrences(rows)}${referenceSource()}`;}catch(e){referenceError(e,()=>referencePlace(value,page))}}
