const originalOpenDialog=openDialog;openDialog=function(title,html){$('#dialog').classList.remove('atlas-dialog');++referenceState.dialogStamp;return originalOpenDialog(title,html)};
function referenceFirstMention(p,item){const who=item.link_td_id;if(!who)return true;const first=(p.ExtRef_Children_people||[]).filter(x=>x.link_td_id===who).reduce((a,b)=>b.start_index<a.start_index?b:a,item);return first===item}
function referenceShortYear(year){return year<0?'前'+(-year):String(year)}
async function referenceLocalPerson(identity){const stamp=referenceState.dialogStamp+1;openDialog('刘恭 · 赤眉时期','<p>正在载入校订人物资料…</p>');try{const data=await peopleIndex();const mentions=(data.byName['刘恭']||[]).map(i=>data.occurrences[i]).filter(x=>x.y>=23&&x.y<=30);mentions.push({c:43,s:1,p:14,y:25});const rows=[...new Map(mentions.map(x=>[`${x.c}:${x.s}:${x.p}`,x])).values()].sort((a,b)=>a.y-b.y||a.c-b.c||a.s-b.s||a.p-b.p);const chapters=await Promise.all(rows.map(x=>peopleChapter(x.c)));if(stamp!==referenceState.dialogStamp||!$('#dialog').open)return;$('#dialog').classList.add('person-dialog');$('#dialog-body').innerHTML=`<div class="person-intro"><strong>刘恭</strong><span> 生卒年不详</span><p>刘盆子的兄长。曾受赤眉派遣向光武帝请求投降，后为更始帝报仇，杀谢禄并自系狱，获赦。</p></div><div class="person-layout"><aside class="person-facts"><h3>人物关系</h3><p>刘盆子是刘恭的弟弟。</p><p class="search-status">本段原资料误用了刘盆子的人物编号，现已分开。没有可靠出生年，不显示年龄。</p><h3>依据</h3><p>本书 26 年正文写“密教弟盆子”，刘恭称“恭弟”；27 年正文记乞降及杀谢禄。下方段落可返回原文核对。</p></aside><section class="person-occurrences"><h3>相关段落 ${rows.length} 段</h3>${rows.map((r,i)=>{const p=chapters[i][r.s].paragraphs[r.p];return `<article class="person-occurrence"><div class="person-occurrence-title"><span>${E(personYear(r.y))}</span><button data-location="${E(JSON.stringify({book:'epub2',chapter:r.c,segment:r.s,paragraph:r.p}))}">${E(state.books.find(b=>b.id==='epub2').chapters[r.c].title)} / 第${r.p+1}段 ↗</button></div><p class="person-snippet">${personExcerpt(p.o,['刘恭','劉恭'])}</p><details><summary>展开译文</summary><p class="translated">${E(p.t||'暂无译文')}</p></details></article>`}).join('')}</section></div>`}catch(e){referenceError(e,()=>referenceLocalPerson(identity))}}
const selectionTools=document.createElement('div');selectionTools.className='selection-tools';selectionTools.hidden=true;selectionTools.innerHTML='<button data-selection-action="lexicon">字词</button><button data-selection-action="note">写批注</button><button data-selection-action="materials">资料</button><button data-selection-action="copy">复制</button>';document.body.append(selectionTools);let readingSelection=null;
$('#content').addEventListener('pointerup',()=>setTimeout(()=>{const selection=window.getSelection();if(!selection||selection.isCollapsed){selectionTools.hidden=true;return}const element=selection.anchorNode?.parentElement,paragraph=element?.closest('.paragraph');if(!paragraph){selectionTools.hidden=true;return}const p=+paragraph.dataset.p,text=captureReadingQuote(segments[state.segment].paragraphs[p].o)||selection.toString().trim();if(!text||text.length>500){selectionTools.hidden=true;return}const range=selection.getRangeAt(0).getBoundingClientRect();readingSelection={p,text};selectionTools.hidden=false;selectionTools.style.left=Math.max(8,Math.min(innerWidth-selectionTools.offsetWidth-8,range.left))+'px';selectionTools.style.top=Math.max(8,range.top-selectionTools.offsetHeight-9)+'px'},0));
selectionTools.addEventListener('pointerdown',e=>e.preventDefault());selectionTools.addEventListener('click',e=>{const action=e.target.closest('[data-selection-action]')?.dataset.selectionAction;if(!action||!readingSelection)return;const {p,text}=readingSelection;selectionTools.hidden=true;if(action==='note')paragraphDialog(p);if(action==='materials'){const r=segments[state.segment].paragraphs[p];if(r.reference)referenceMaterial(r.reference.tongjian_id);else paragraphDialog(p)}if(action==='lexicon'){actions.lexicon();$('#lexicon-query').value=text;$('#lexicon-form').requestSubmit()}if(action==='copy')navigator.clipboard?.writeText(text).then(()=>toast('选文已复制')).catch(()=>toast('请使用复制快捷键'));});
$('#reading').addEventListener('scroll',()=>selectionTools.hidden=true,{passive:true});document.addEventListener('keydown',e=>{if(e.key==='Escape')selectionTools.hidden=true});

