async function referenceLibrary(){const stamp=referenceState.dialogStamp+1;openDialog('史料资料库','<p>正在载入书目…</p>');try{const d=await referenceAPI('background-materials/books');if(stamp!==referenceState.dialogStamp||!$('#dialog').open)return;$('#dialog-body').innerHTML=`<form id="library-search" class="row"><input id="library-query" aria-label="搜索史料" placeholder="搜索二十四史、容斋随笔"><button class="primary">搜索</button></form>${(d.categories||[]).map(c=>`<h3>${E(c.category)}</h3><div class="library-books">${c.books.map(b=>`<button data-library-book="${E(b.name)}">${E(b.name)}</button>`).join('')}</div>`).join('')}${referenceSource()}`;$('#library-search').onsubmit=e=>{e.preventDefault();referenceLibrarySearch($('#library-query').value.trim())}}catch(e){referenceError(e,referenceLibrary)}}
async function referenceLibraryToc(name){const stamp=referenceState.dialogStamp+1;openDialog('资料目录 · '+name,'<p>正在载入目录…</p>');try{const d=await referenceAPI('background-materials/toc',{name});if(stamp!==referenceState.dialogStamp||!$('#dialog').open)return;const tree=rows=>rows.map(x=>(x.children||[]).length?`<details><summary>${E(x.label)}</summary>${tree(x.children)}</details>`:`<p><button data-ref-passage="${E(x.tongjian_id)}">${E(x.label)}</button></p>`).join('');$('#dialog-body').innerHTML=`<button data-library-home>全部书目</button><div class="library-toc">${tree(d.tree||[])}</div>${referenceSource()}`}catch(e){referenceError(e,()=>referenceLibraryToc(name))}}
async function referencePassage(params){const stamp=referenceState.dialogStamp+1;openDialog('资料库全文','<p>正在载入全文…</p>');try{const d=await referenceAPI('background-materials/passage',params);if(stamp!==referenceState.dialogStamp||!$('#dialog').open)return;$('#dialog-title').textContent='资料库 · '+d.name;$('#dialog-body').innerHTML=`<div class="reference-paging"><button data-library-book="${E(d.name)}">书目目录</button><button data-library-name="${E(d.name)}" data-library-page="${d.page-1}" ${d.page<=1?'disabled':''}>上一页</button><span>${d.page}/${d.total_pages} · 共${d.total}段</span><button data-library-name="${E(d.name)}" data-library-page="${d.page+1}" ${d.page>=d.total_pages?'disabled':''}>下一页</button></div><div class="reference-article">${(d.passages||[]).map(p=>`<article id="material-${E(p.tongjian_id)}" ${p.tongjian_id===d.anchor_id?'class="material-anchor"':''}><h3>${E(p.path)}</h3><p>${E(p.content_jianti||p.content||'')}</p>${p.content_fanyi?`<p class="translated">${E(p.content_fanyi)}</p>`:''}${(p.zztj_links||[]).map(l=>`<button data-library-link="${E(l.target_paragraph_tongjian_id||l.paragraph_tongjian_id||'')}">${E(l.target_path||'查看通鉴关联段落')}</button>`).join('')}</article>`).join('')}</div>${referenceSource()}`;if(params.tongjian_id)document.getElementById('material-'+d.anchor_id)?.scrollIntoView({block:'start'})}catch(e){referenceError(e,()=>referencePassage(params))}}
async function referenceLibrarySearch(query,page=1){if(!query)return;const stamp=referenceState.dialogStamp+1;openDialog('史料搜索 · '+query,'<p>正在查找…</p>');try{const d=await referenceAPI('background-materials/search',{query,page,page_size:10});if(stamp!==referenceState.dialogStamp||!$('#dialog').open)return;const rows=d.items||d.results||d.passages||[];$('#dialog-body').innerHTML=`<button data-library-home>全部书目</button><p>共 ${d.total||0} 条</p>${rows.map(p=>`<article class="person-occurrence"><button data-ref-passage="${E(p.tongjian_id||p.id)}">${E(p.name)} · ${E(p.path)}</button><p>${referenceHTML(p.content_jianti||p.content||p.snippet||'')}</p></article>`).join('')||'<p>暂无结果</p>'}<div class="reference-paging"><button data-library-query="${E(query)}" data-library-search-page="${page-1}" ${page<=1?'disabled':''}>上一页</button><span>${page}/${d.total_pages||Math.max(1,Math.ceil((d.total||0)/10))}</span><button data-library-query="${E(query)}" data-library-search-page="${page+1}" ${page*10>=(d.total||0)?'disabled':''}>下一页</button></div>${referenceSource()}`}catch(e){referenceError(e,()=>referenceLibrarySearch(query,page))}}
actions.library=referenceLibrary;const libraryButton=document.createElement('button');libraryButton.dataset.action='library';libraryButton.textContent='史料资料库 · 二十四史';backupTools.append(libraryButton);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.libraryBook)referenceLibraryToc(b.dataset.libraryBook);else if(b.dataset.libraryPage)referencePassage({name:b.dataset.libraryName,page:b.dataset.libraryPage});else if(b.dataset.libraryQuery)referenceLibrarySearch(b.dataset.libraryQuery,+b.dataset.librarySearchPage);else if(b.hasAttribute('data-library-home'))referenceLibrary();else if(b.dataset.libraryLink){const id=b.dataset.libraryLink;referenceAPI('brief',{tongjian_id:id,type:'paragraph'}).then(d=>{const p=d.paragraph||d;if(p.content){referenceState.paragraphs.set(id,p);referenceJump(id)}else toast('暂未找到关联原文')}).catch(e=>toast(e.message))}});
async function officialsDialog(){openDialog('历代官制','<div class="row"><select id="officials-dynasty" aria-label="官制时代">'+[['zhou','周'],['qin','秦'],['xihan','西汉'],['donghan','东汉'],['sanguo','三国'],['xijin','西晋'],['dongjin','东晋十六国'],['nanbeichao','南北朝'],['sui','隋'],['tang','唐'],['wudaishiguo','五代十国']].map(([id,name])=>`<option value="${id}">${name}</option>`).join('')+'</select><input id="officials-filter" aria-label="筛选官职" placeholder="查找官职或机构"></div><div id="officials-tree"></div>');const box=$('#officials-tree'),select=$('#officials-dynasty');let data=null;const draw=()=>{if(!data||!box.isConnected)return;const q=$('#officials-filter').value.trim();function node(n){const kids=(n.children||[]).map(node).join(''),self=!q||[n.name,n.description,JSON.stringify(n.details||{})].join('').includes(q);if(!self&&!kids)return '';return `<details class="official-node" ${q?'open':''}><summary>${E(n.name)}</summary><p>${E(n.description||'')}</p>${Object.entries(n.details||{}).map(([k,v])=>`<p>${E(typeof v==='string'?v:JSON.stringify(v))}</p>`).join('')}<div>${kids}</div></details>`}box.innerHTML=`<h3>${E(data.title)}</h3><p>${E(data.meta?.period||'')}</p>${(data.meta?.notes||[]).map(n=>`<p>${E(n)}</p>`).join('')}${node(data.root)||'<p>没有找到匹配的官职</p>'}${referenceSource()}`};select.onchange=async()=>{const value=select.value;box.textContent='正在载入…';try{const r=await fetch('data/officials/'+value+'.json');const d=await r.json();if(!box.isConnected||select.value!==value)return;data=d;draw()}catch(e){if(box.isConnected)box.textContent='官制资料暂时无法载入'}};$('#officials-filter').oninput=draw;select.onchange()}
actions.officials=officialsDialog;const officialsButton=document.createElement('button');officialsButton.dataset.action='officials';officialsButton.textContent='历代官制 · 机构与品阶';backupTools.append(officialsButton);
